/* Keep the decorative leave-day close SVG on its existing button hit target. */
[data-close-leave-day-modal] .app-icon,
[data-close-leave-day-modal] .app-icon * { pointer-events: none; }
/* These existing mobile controls measured below the shared 44px target. */
[data-close-leave-day-modal], #sidebar-toggle, #sidebar-close { min-width: 44px; min-height: 44px; }
